'use strict';
/* Component functions return HTML. UI state lives in memory; no API requests. */
const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5z M10 21h4',network:'M9 3h6v6H9z M3 16h6v5H3z M15 16h6v5h-6z M12 9v4 M6 16v-3h12v3',pulse:'M2 12h5l3-8 4 16 3-8h5',chart:'M4 3v17h17 M7 14l4-5 4 3 5-7',layers:'M12 3l10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c-5 5-5 13 0 18 M12 3c5 5 5 13 0 18',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 4a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-4',cpu:'M6 6h12v12H6z M9 9h6v6H9z M9 2v4 M15 2v4 M9 18v4 M15 18v4 M2 9h4 M2 15h4 M18 9h4 M18 15h4',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',archive:'M3 3h18v5H3z M5 8v13h14V8 M9 12h6',sliders:'M4 3v6 M4 15v6 M12 3v11 M12 20v1 M20 3v1 M20 10v11 M1 9h6v6H1z M9 14h6v6H9z M17 4h6v6h-6z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M9 8a3 3 0 0 1 6 1c0 2-3 2-3 5 M12 17v.1',logout:'M9 3H3v18h6 M9 12h12 M17 8l4 4-4 4',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M15 15l6 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',plus:'M12 5v14 M5 12h14',close:'M5 5l14 14 M5 19L19 5',moon:'M20 15a9 9 0 0 1-11-11 9 9 0 1 0 11 11',menu:'M4 6h16 M4 12h16 M4 18h16',check:'M4 12l5 5L20 6',refresh:'M20 7V3l-4 1 M20 7a8 8 0 1 0 0 10',server:'M3 3h18v7H3z M3 14h18v7H3z M7 6v1 M7 17v1',lock:'M5 10h14v11H5z M8 10V7a4 4 0 0 1 8 0v3'};
const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[name]||icons.grid}"/></svg>`;
const state={role:'Admin',period:'24h',users:SOC.users.map(x=>({...x})),ips:SOC.ips.map(x=>({...x})),alerts:SOC.alerts.map(x=>({...x})),activities:[...SOC.activities],settings:{},filter:{q:'',severity:'All',type:'All',status:'All'},report:{from:'2026-10-19',to:'2026-10-22',severity:'All',type:'All'},archiveQ:'',activityQ:'',selected:'ALT-2048',lookup:null};
let route='dashboard';
const adminRoutes=['users','network-settings','ai-settings','ip-manager','alert-settings'];
const badge=(text)=>`<span class="badge ${esc(text.toLowerCase().replaceAll(' ','-'))}">${esc(text)}</span>`;
const btn=(text,action,ico='',primary=false)=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${action}">${ico?icon(ico):''}${text}</button>`;
const pageHead=(title,description,actions='',eyebrow='Security operations')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${description}</p></div><div class="actions">${actions}</div></div>`;
const panelHead=(title,desc='',action='')=>`<div class="panel-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;
const select=(name,values,value)=>`<select name="${name}" id="${name}">${values.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select>`;
const field=(label,control,wide=false)=>`<label class="field ${wide?'wide':''}">${label}${control}</label>`;
const notice=(text='Interactive prototype. All telemetry and records are illustrative; no live network is connected.')=>`<div class="notice">${text}</div>`;
function stat(label,value,foot,ico,trend='',bad=false){return `<article class="panel stat"><div class="stat-top">${label}<span class="stat-symbol">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-bottom">${trend?`<span class="trend ${bad?'bad':''}">${trend}</span>`:''}<span>${foot}</span></div></article>`}
function nav(){let last='';return SOC.routes.filter(r=>r[0]!=='login').map(([id,title,ico,group])=>{let h=group!==last?`<div class="nav-label">${group}</div>`:'';last=group;return h+`<a class="nav-link ${id===route?'active':''}" ${id===route?'aria-current="page"':''} href="#${id}">${icon(ico)}${title}${id==='alerts'?`<span class="count">${state.alerts.filter(x=>x.status!=='Closed').length}</span>`:''}</a>`}).join('')}
function shell(content){return `<div class="app-shell"><aside class="sidebar" aria-label="Main navigation"><a class="brand" href="#dashboard"><span class="brand-mark">${icon('shield')}</span><div><strong>sentinel<span style="color:var(--accent)">.</span></strong><small>SECURITY OPERATIONS</small></div></a><nav>${nav()}</nav><div class="sidebar-bottom"><a class="profile" href="#login"><span class="avatar">${state.role==='Admin'?'AM':'JC'}</span><div><strong>${state.role==='Admin'?'Alex Morgan':'Jamie Chen'}</strong><small>${state.role} demo · Switch role ↗</small></div></a></div></aside><div class="shell-body"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb">Workspace <span>/</span> <b>${SOC.routes.find(x=>x[0]===route)?.[1]||'Dashboard'}</b></div><div class="top-actions"><button class="top-search" data-action="search">${icon('search')} Search workspace <kbd>/</kbd></button><span class="demo-label"><i class="dot"></i> DEMO WORKSPACE</span><button class="icon-btn" data-action="theme" aria-label="Toggle light or dark theme">${icon('moon')}</button><a class="icon-btn" href="#alerts" aria-label="View alerts">${icon('bell')}</a></div></header><main id="main" tabindex="-1"><div class="route-enter">${content}</div><footer class="footer"><span>Sentinel SOC · Web Technologies semester project</span><span>UI prototype / Sample dataset · 22 Oct 2026</span></footer></main></div></div>`}
function segments(){return `<div class="segments" aria-label="Chart period">${['24h','7d','30d'].map(p=>`<button data-period="${p}" class="${state.period===p?'active':''}" aria-pressed="${state.period===p}">${p==='24h'?'24 hours':p==='7d'?'7 days':'30 days'}</button>`).join('')}</div>`}
function lineChart(){let d=SOC.traffic[state.period];const pts=a=>a.map((v,i)=>`${42+i*550/(a.length-1)},${166-v*2.6}`).join(' ');return `<div class="chart-wrap"><svg class="line-chart" viewBox="0 0 610 205" role="img" aria-label="Illustrative ${state.period} traffic chart, normal and malicious traffic in thousands of packets per interval"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#4a9179" stop-opacity=".2"/><stop offset="100%" stop-color="#4a9179" stop-opacity="0"/></linearGradient></defs>${[0,15,30,45,60].map(v=>`<line class="gridline" x1="42" x2="592" y1="${166-v*2.6}" y2="${166-v*2.6}"/><text x="2" y="${170-v*2.6}" class="chart-text">${v}k</text>`).join('')}<polygon points="42,166 ${pts(d.normal)} 592,166" fill="url(#area)"/><polyline points="${pts(d.normal)}" fill="none" stroke="#40836d" stroke-width="2.5" stroke-linejoin="round"/><polyline points="${pts(d.malicious)}" fill="none" stroke="#b77b86" stroke-width="2" stroke-linejoin="round"/>${d.labels.map((x,i)=>`<text x="${42+i*550/(d.labels.length-1)}" y="194" text-anchor="${i===0?'start':i===d.labels.length-1?'end':'middle'}" class="chart-text">${x}</text>`).join('')}</svg></div><div class="chart-legend"><span><i class="legend-mark"></i>Normal traffic</span><span><i class="legend-mark red"></i>Malicious traffic</span><span style="margin-left:auto">Sample · packets / interval</span></div>`}
function donut(){return `<div class="donut-row"><div class="donut" role="img" aria-label="Illustrative distribution of 100 historical alerts: DDoS 42%, port scan 28%, brute force 18%, botnet 12%"><div class="donut-center">100<small>sample alerts</small></div></div><ul class="legend-list">${SOC.attackMix.map(([n,v,c])=>`<li><span><i class="legend-mark" style="background:${c}"></i>${n}</span><b>${v}%</b></li>`).join('')}</ul></div>`}
function alertTable(items,limit){let rows=limit?items.slice(0,limit):items;return `<div class="table-wrap"><table><thead><tr><th>Alert / Time</th><th>Source IP</th><th>Attack type</th><th>Severity</th><th>Confidence</th><th>Status</th><th><span class="muted">Details</span></th></tr></thead><tbody>${rows.map(a=>`<tr><td><b>${a.id}</b><div class="help">${a.time}</div></td><td class="mono">${a.source}</td><td>${a.type}</td><td>${badge(a.severity)}</td><td><span class="confidence"><i><b style="width:${a.confidence}%"></b></i>${a.confidence}%</span></td><td>${badge(a.status)}</td><td><a class="icon-btn" style="width:27px;height:27px;box-shadow:none" href="#threat-details/${a.id}" aria-label="Inspect ${a.id}">${icon('chevron')}</a></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No alerts match your filters.</td></tr>'}</tbody></table></div>`}
function dashboard(){let active=state.alerts.filter(a=>a.status!=='Closed').length;return pageHead('Security overview','Your network at a glance. Every signal, in one place.',`<a class="btn" href="#traffic-history">${icon('clock')}22 Oct 2026</a><a class="btn primary" href="#reports">${icon('download')}Export report</a>`)+`<div class="stats">${stat('Active threats',active,'in sample alert queue','shield',state.alerts.filter(a=>a.severity==='Critical'&&a.status!=='Closed').length+' critical',true)}${stat('Traffic analyzed','1.28M','illustrative packets today','chart','↑ 12.8%')}${stat('Detection confidence','98.6%','illustrative model average','cpu','Sample')}${stat('Sensors online','2 / 2','all sample sensors healthy','network','● Operational')}</div><div class="dash-grid"><section class="panel">${panelHead('Network activity','Normal and malicious traffic over time',segments())}${lineChart()}</section><section class="panel">${panelHead('Attack distribution','Historical sample · 100 alerts','<a class="link-btn" href="#attack-types">Explore ↗</a>')}${donut()}<div class="health-strip"><span>Most frequent <strong>DDoS</strong></span><span>4 attack categories</span></div></section></div><section class="panel">${panelHead('Recent alerts','Prioritize, investigate, and resolve suspicious activity.','<a class="link-btn" href="#alerts">View all alerts →</a>')}${alertTable(state.alerts,5)}<div class="table-foot"><span><i class="dot"></i> Sample feed · Updated at 14:42:08</span><span>Showing 5 of ${state.alerts.length} alerts</span></div></section><div class="health-strip" style="border:0;margin:23px 4px 0;padding:0"><span>${icon('server')} <strong>System health</strong> &nbsp; All sample services operational</span><a href="#system-health">View infrastructure →</a></div>`}
function filteredAlerts(){return state.alerts.filter(a=>(state.filter.severity==='All'||a.severity===state.filter.severity)&&(state.filter.type==='All'||a.type===state.filter.type)&&(state.filter.status==='All'||a.status===state.filter.status)&&[a.id,a.source,a.destination,a.type].join(' ').toLowerCase().includes(state.filter.q.toLowerCase()))}
function alertsPage(){return pageHead('Threat alerts','Investigate the signals that need your attention.',btn('Export CSV','export-alerts','download'))+`<section class="panel"><div class="filters">${field('Search alerts',`<input id="alert-q" placeholder="IP address or alert ID" value="${esc(state.filter.q)}">`)}${field('Severity',select('alert-severity',['All','Critical','High','Medium','Low'],state.filter.severity))}${field('Attack type',select('alert-type',['All',...SOC.attackMix.map(x=>x[0])],state.filter.type))}${field('Status',select('alert-status',['All','Open','Investigating','Closed'],state.filter.status))}${btn('Reset','reset-alerts','refresh')}</div><div id="alert-results">${alertTable(filteredAlerts())}<div class="table-foot">${filteredAlerts().length} matching alerts · Sample dataset</div></div></section>`}
function detailPage(){let a=state.alerts.find(a=>a.id===state.selected)||state.alerts[0];return pageHead('Threat investigation',`${a.id} · Detected ${a.date} at ${a.time}`,'<a class="btn" href="#alerts">← Back to alerts</a>'+btn('Quick summary','summary','file'),'Incident workspace')+`<div class="two-grid"><section class="panel">${panelHead(a.type+' detected','Sample alert explanation',badge(a.severity))}<div class="notice">${a.reason} This explanation is a prepared UI example, not AI inference.</div><dl class="detail-list">${Object.entries({'Source IP':a.source,'Destination IP':a.destination,'Protocol':a.protocol,'Sensor':a.sensor,'Flow duration':a.duration,'Data transferred':a.bytes,'Confidence':a.confidence+'%','Status':a.status}).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="actions">${btn('Mark investigating','investigate','search',true)}${btn('Close alert','close-alert','check')}${state.role==='Admin'?btn('Block IP (demo)','block-threat','shield'):''}</div></section><section class="panel">${panelHead('Investigation timeline','Illustrative sequence of events')}<div class="timeline"><div class="timeline-item"><strong>Flow captured</strong><p>${a.time} · ${a.sensor} · ${a.protocol}</p></div><div class="timeline-item"><strong>Pattern classified</strong><p>${a.type} · ${a.confidence}% sample confidence</p></div><div class="timeline-item"><strong>Alert added to queue</strong><p>Severity: ${a.severity} · Current status: ${a.status}</p></div></div><a class="btn" href="#network-map">${icon('network')}Explore connection path</a></section></div>`}
function networkPage(){return pageHead('Network topology','Trace the connection between source, sensor, and protected assets.',`<a class="btn" href="#threat-details/${state.selected}">Inspect selected flow ${icon('arrow')}</a>`)+notice('Illustrative topology. Select a source node to inspect its sample alert. No network scan is performed.')+`<section class="panel">${panelHead('Monitored environment','2 sensors · 4 protected hosts · Sample topology',badge('Demo'))}<svg class="network-svg" viewBox="0 0 900 360" role="img" aria-label="Two suspicious sources connect through a gateway and NIDS sensors to internal targets"><path class="edge" d="M165 95L360 180 M165 270L360 180 M450 180L570 90 M450 180L570 270 M650 90L780 90 M650 270L780 270"/><a href="#threat-details/ALT-2048" aria-label="DDoS source 203.0.113.24"><rect class="node" x="25" y="60" rx="16" width="170" height="75"/><text x="110" y="91" text-anchor="middle">203.0.113.24</text><text x="110" y="114" text-anchor="middle" style="fill:#af435b;font-size:10px">DDoS source · Critical</text></a><a href="#threat-details/ALT-2047" aria-label="Port scan source"><rect class="node" x="25" y="235" rx="16" width="170" height="75"/><text x="110" y="266" text-anchor="middle">198.51.100.18</text><text x="110" y="289" text-anchor="middle" style="fill:#946315;font-size:10px">Port scan · High</text></a><rect class="node" x="310" y="140" rx="18" width="150" height="80"/><text x="385" y="174" text-anchor="middle">Network gateway</text><text x="385" y="197" text-anchor="middle">10.0.0.1</text>${[[530,50,'NIDS-01'],[530,230,'NIDS-02'],[730,50,'10.0.0.12'],[730,230,'10.0.0.24']].map(([x,y,n])=>`<rect class="node" x="${x}" y="${y}" rx="16" width="145" height="80"/><text x="${x+72}" y="${y+37}" text-anchor="middle">${n}</text><text x="${x+72}" y="${y+59}" text-anchor="middle" style="font-size:10px">${n.startsWith('NIDS')?'Sample sensor':'Protected asset'}</text>`).join('')}</svg><div class="chart-legend"><span><i class="legend-mark"></i>Monitored connection</span><span><i class="legend-mark red"></i>Suspicious source</span></div></section>`}
function healthPage(){return pageHead('System health','A clear view of the services behind your security operations.',btn('Refresh sample','refresh-health','refresh'))+notice()+`<div class="stats">${stat('Service availability','100%','illustrative uptime','pulse')}${stat('Ingest latency','24 ms','sample processing delay','clock')}${stat('CPU utilization','32%','sample NIDS server load','cpu')}${stat('Memory usage','4.2 GB','of 16 GB provisioned','server')}</div><div class="two-grid">${[['NIDS server','Ubuntu host · NIDS-01',32],['Zeek service','Flow metadata processor',24],['Python service','Feature preparation pipeline',41],['AI model','Sample classifier · v1.0',18]].map(([n,d,v])=>`<section class="panel">${panelHead(n,d,badge('Operational'))}<div class="service-head"><span>Illustrative resource utilization</span><b>${v}%</b></div><div class="progress"><span style="width:${v}%"></span></div><p class="help">Last sample: 22 Oct 2026, 14:42 · No service is connected.</p></section>`).join('')}</div>`}
function usersPage(){return pageHead('User management','Manage demonstration accounts and workspace roles.',btn('Add user','add-user','plus',true),'Administration')+notice('Changes affect this browser session only. Demo roles control visible editing actions; they are not authentication or authorization.')+`<section class="panel">${panelHead('Workspace members',`${state.users.length} sample accounts`)}<div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><b>${esc(u.name)}</b></td><td>${esc(u.email)}</td><td>${badge(u.role)}</td><td>${badge(u.status)}</td><td><button class="link-btn" data-edit-user="${u.id}">Edit</button> <button class="link-btn" style="color:var(--red)" data-delete-user="${u.id}">Delete</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No demo users. Add a user to get started.</td></tr>'}</tbody></table></div></section>`}
function settingsPage(kind){let s=state.settings[kind]||{};let content='';if(kind==='network-settings')content=`<div class="form-grid">${field('Sensor name',`<input name="sensor" required maxlength="40" value="${esc(s.sensor||'NIDS-01')}">`)}${field('Capture interface',select('interface',['eth0','eth1','wlan0'],s.interface||'eth0'))}${field('Sensor address',`<input name="address" required value="${esc(s.address||'10.0.0.10')}" placeholder="10.0.0.10">`)}${field('Monitored subnet (CIDR)',`<input name="subnet" required value="${esc(s.subnet||'10.0.0.0/24')}">`)}${field('Packet capture mode',select('capture',['Passive monitoring','Mirrored traffic'],s.capture||'Passive monitoring'))}${field('Sample interval (seconds)',`<input name="interval" type="number" min="1" max="60" value="${esc(s.interval||'5')}" required>`)}</div>${toggle('enabled','Sensor enabled','Display the sensor as enabled in this saved demo configuration.',s.enabled!==false)}`;
if(kind==='ai-settings')content=`<div class="form-grid">${field('Model profile',select('model',['NIDS classifier v1.0','Experimental classifier v2.0'],s.model||'NIDS classifier v1.0'))}${field('Detection mode',select('mode',['Balanced','Sensitive','Conservative'],s.mode||'Balanced'))}${field('Confidence threshold: <output id="threshold-value">'+(s.threshold||85)+'%</output>',`<input type="range" name="threshold" min="50" max="99" value="${esc(s.threshold||85)}">`,true)}</div><p class="help">This value is saved in UI memory. It does not change the prepared alerts or run a model.</p>${toggle('anomaly','Anomaly detection','Include anomaly signals in the demonstration configuration.',s.anomaly!==false)}${toggle('explanations','Show explanations','Preference for a future connected implementation.',s.explanations!==false)}`;
if(kind==='alert-settings')content=`<div class="form-grid">${field('Notification severity',select('severity',['Critical only','High and critical','All severities'],s.severity||'High and critical'))}${field('Digest schedule',select('digest',['Immediately','Hourly','Daily'],s.digest||'Immediately'))}${field('Demo email recipient',`<input type="email" name="email" value="${esc(s.email||'analyst@example.com')}" required>`)}${field('Demo phone',`<input name="phone" value="${esc(s.phone||'+00 000 0000000')}" maxlength="25">`)}</div>${toggle('emailEnabled','Email notifications','UI preference only; no email is sent.',s.emailEnabled!==false)}${toggle('sms','SMS notifications','UI preference only; no SMS service is connected.',!!s.sms)}${toggle('slack','Slack notifications','UI preference only; no Slack workspace is connected.',!!s.slack)}`;
const meta={'network-settings':['Network settings','Configure the appearance of your sensor setup.','Sensor configuration'],'ai-settings':['AI settings','Tune demonstration detection preferences.','Detection preferences'],'alert-settings':['Alert settings','Choose how your workspace would notify analysts.','Notification preferences']}[kind];return pageHead(meta[0],meta[1],'','Configuration')+notice('UI-only configuration. Saving changes updates session memory; it does not configure a server, model, sensor, or notification provider.')+`<section class="panel" style="max-width:880px">${panelHead(meta[2],s.saved?'Saved for this session':'Unsaved changes are discarded when leaving this screen')}<form id="settings-form" data-kind="${kind}">${content}<div class="actions" style="margin-top:25px"><button class="btn primary" type="submit">${icon('check')}Save demo settings</button>${btn('Reset defaults','reset-settings','refresh')}${kind==='alert-settings'?btn('Preview notification','preview-notification','bell'):''}</div></form></section>`}
function toggle(name,title,desc,checked){return `<label class="setting-row"><span><strong>${title}</strong><p>${desc}</p></span><span class="switch"><input type="checkbox" name="${name}" ${checked?'checked':''}><span></span></span></label>`}
function ipPage(){return pageHead('IP manager','Keep trusted and suspicious addresses organized.',btn('Add IP policy','add-ip','plus',true),'Administration')+notice('Policies are sample UI records. No traffic is blocked or permitted on a real network.')+`<section class="panel">${panelHead('IP policies',`${state.ips.length} session records`)}<div class="table-wrap"><table><thead><tr><th>IP address</th><th>Policy</th><th>Reason</th><th>Added</th><th>Actions</th></tr></thead><tbody>${state.ips.map(x=>`<tr><td class="mono">${esc(x.ip)}</td><td>${badge(x.policy)}</td><td>${esc(x.reason)}</td><td>${x.added}</td><td><button class="link-btn" data-toggle-ip="${x.id}">${x.policy==='Blocked'?'Allow':'Block'} (demo)</button><button class="link-btn" data-delete-ip="${x.id}" style="color:var(--red)">Remove</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No IP policies. Add a policy to begin.</td></tr>'}</tbody></table></div></section>`}
function reportRows(){return state.alerts.filter(a=>a.date>=state.report.from&&a.date<=state.report.to&&(state.report.severity==='All'||a.severity===state.report.severity)&&(state.report.type==='All'||a.type===state.report.type))}
function reportsPage(){let rows=reportRows();return pageHead('Security reports','Build an incident summary from the sample dataset.',btn('Download CSV','export-report','download')+btn('Print / Save PDF','print','file',true),'Reporting')+`<section class="panel" style="margin-bottom:24px"><div class="filters" style="margin-bottom:0">${field('From',`<input type="date" id="report-from" value="${state.report.from}">`)}${field('To',`<input type="date" id="report-to" value="${state.report.to}">`)}${field('Severity',select('report-severity',['All','Critical','High','Medium','Low'],state.report.severity))}${field('Attack type',select('report-type',['All',...SOC.attackMix.map(x=>x[0])],state.report.type))}</div></section><section class="panel" id="report-results">${panelHead('Incident report',`${state.report.from} to ${state.report.to} · ${rows.length} matching records`)}${notice('SAMPLE REPORT · Educational UI demonstration. These records are not evidence of real incidents.')}${alertTable(rows)}<p class="help">Print / Save PDF opens your browser print dialog. Choose “Save as PDF” where supported.</p></section>`}
function archivePage(){let rows=state.alerts.filter(a=>[a.id,a.source,a.type,a.date].join(' ').toLowerCase().includes(state.archiveQ.toLowerCase()));return pageHead('Log archive','Search and export the prepared security log collection.',btn('Download CSV','export-archive','download'))+`<section class="panel">${field('Search saved sample logs',`<input id="archive-q" value="${esc(state.archiveQ)}" placeholder="Search IP, date, category, or alert ID">`)}<div id="archive-results">${archiveTable(rows)}</div></section>`}
function archiveTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Record</th><th>Source</th><th>Category</th><th>Sensor</th><th>Action</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${a.date} <span class="mono">${a.time}</span></td><td>${a.id}</td><td class="mono">${a.source}</td><td>${a.type}</td><td>${a.sensor}</td><td><a class="link-btn" href="#threat-details/${a.id}">View log →</a></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No archived records match.</td></tr>'}</tbody></table></div><div class="table-foot">${rows.length} sample log records</div>`}
function trafficPage(){let d=SOC.traffic[state.period];let sum=a=>a.reduce((x,y)=>x+y,0);return pageHead('Traffic history','Explore normal and suspicious traffic across sample time windows.',btn('Download chart data','export-traffic','download'),'Historical analytics')+`<section class="panel" style="margin-bottom:24px">${panelHead('Traffic over time','Illustrative packet counts per time interval',segments())}${lineChart()}</section><div class="three-grid">${stat('Normal packets',sum(d.normal)+'k','selected sample window','chart')}${stat('Malicious packets',sum(d.malicious)+'k','selected sample window','shield')}${stat('Malicious share',(100*sum(d.malicious)/(sum(d.normal)+sum(d.malicious))).toFixed(1)+'%','calculated from this chart','pulse')}</div>`}
function attackPage(){return pageHead('Attack types','Understand the composition of the historical sample.',btn('Download distribution','export-types','download'),'Historical analytics')+`<div class="two-grid"><section class="panel">${panelHead('Attack distribution','Separate historical fixture · 100 sample alerts')}${donut()}</section><section class="panel">${panelHead('Category frequency','Counts from the same 100-alert historical fixture')}${SOC.attackMix.map(([n,v,c])=>`<div class="bar-row"><span>${n}</span><div class="bar"><b style="width:${v*2}%;background:${c}"></b></div><b>${v}</b></div>`).join('')}</section></div><section class="panel">${panelHead('Category guide','Short descriptions for the interface demonstration')}<div class="two-grid" style="margin:0">${[['DDoS','Traffic bursts directed at the availability of a service.'],['Port scan','Connection probes across ports or destination services.'],['Brute force','Repeated attempts to guess authentication credentials.'],['Botnet','Coordinated or periodic communication from compromised hosts.']].map(([n,d])=>`<div><h3>${n}</h3><p class="help">${d}</p></div>`).join('')}</div></section>`}
function intelPage(){let a=state.lookup?state.alerts.find(x=>x.source===state.lookup):null;return pageHead('Threat intelligence','Inspect a prepared reputation profile for a sample address.','','Intelligence workspace')+notice('Offline demonstration only. This lookup uses bundled fixtures and never contacts a threat intelligence provider.')+`<section class="panel" style="margin-bottom:24px">${panelHead('IP reputation lookup','Try 203.0.113.24 or 198.51.100.18')}<form id="lookup-form" class="filters" style="margin-bottom:0">${field('IPv4 address',`<input name="ip" required value="${esc(state.lookup||'')}" placeholder="203.0.113.24">`)}<button class="btn primary" type="submit">${icon('search')}Check sample reputation</button></form></section>${state.lookup?(a?`<div class="two-grid"><section class="panel">${panelHead(state.lookup,'Prepared reputation profile',badge(a.severity))}<div class="metric-large">${a.confidence}%</div><p class="help">Illustrative confidence, not a verified reputation score.</p><dl class="detail-list"><div><dt>Sample category</dt><dd>${a.type}</dd></div><div><dt>Associated alert</dt><dd>${a.id}</dd></div><div><dt>Source</dt><dd>Local demo fixture</dd></div><div><dt>External verification</dt><dd>Not performed</dd></div></dl><a class="btn" href="#threat-details/${a.id}">Inspect linked alert →</a></section><section class="panel">${panelHead('Context','What this result means')}<p class="help">This reserved documentation address appears in the sample alert dataset. The result demonstrates how an integrated reputation response could be presented.</p><p class="help">A missing fixture does not mean an address is safe, and a matching fixture does not indicate a real malicious address.</p></section></div>`:`<section class="panel empty"><h2>No sample profile found</h2><p>No bundled entry exists for ${esc(state.lookup)}. No external reputation check was performed.</p></section>`):`<section class="panel empty">${icon('globe')}<h2 style="margin-top:15px">Context starts with an address</h2><p>Enter a sample IP to explore its prepared profile.</p></section>`}`}
function activityRows(){return state.activities.filter(a=>[a.actor,a.action,a.category].join(' ').toLowerCase().includes(state.activityQ.toLowerCase()))}
function activityTable(){return `<div class="table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Activity</th><th>Category</th></tr></thead><tbody>${activityRows().map(a=>`<tr><td class="mono">${esc(a.time)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${badge(a.category)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No matching activities.</td></tr>'}</tbody></table></div>`}
function activityPage(){return pageHead('Activity logs','Review sample history and actions taken during this session.',btn('Export activity','export-activity','download'))+`<section class="panel">${field('Search activity',`<input id="activity-q" placeholder="User, action, or category" value="${esc(state.activityQ)}">`)}<div id="activity-results">${activityTable()}</div><p class="help">Session activity is temporary and resets on reload. This is not an audit trail.</p></section>`}
function helpPage(){return pageHead('Help & metrics','Understand the workspace and the meaning of the demo metrics.','','Resources')+notice('All model metrics below are illustrative placeholders. No model was trained, evaluated, or connected to this frontend.')+`<div class="stats">${stat('Accuracy','98.6%','illustrative only','check')}${stat('Precision','97.8%','illustrative only','shield')}${stat('Recall','96.9%','illustrative only','search')}${stat('F1 score','97.3%','illustrative only','pulse')}</div><div class="two-grid"><section class="panel">${panelHead('Workspace guide','A practical walkthrough')}<details open><summary>How do I investigate an alert?</summary><p>Open Alerts, filter the list, and use the arrow on a row. Threat details shows the sample flow, confidence, and status. Mark investigating or close the alert to update session state.</p></details><details><summary>How do I change roles?</summary><p>Select your profile at the bottom of the sidebar to open Login. Choose Admin or Analyst and enter the demo. The selected role changes editing availability only; no identity is verified.</p></details><details><summary>Where are changes stored?</summary><p>Records and settings are held in JavaScript memory. Reloading resets the demo. There is no database, API, WebSocket connection, or persistent browser storage.</p></details><details><summary>How do exports work?</summary><p>CSV downloads are generated in the browser from the current view. Reports also supports the browser print dialog, where Save as PDF may be selected.</p></details><details><summary>What does confidence mean here?</summary><p>The values are authored fixtures used to demonstrate presentation. They are not measured probabilities or verified model performance.</p></details></section><section class="panel">${panelHead('Project coverage','18 interfaces · 3 modules · 6 per member')}<div class="timeline">${[['A','Shahroz','Login, Dashboard, Alerts, Threat details, Network map, System health'],['B','Asad','User management, Network settings, AI settings, IP manager, Reports, Log archive'],['C','Sumama','Traffic history, Attack types, Threat intelligence, Alert settings, Activity logs, Help & metrics']].map(([m,n,d])=>`<div class="timeline-item"><strong>Module ${m} · ${n}</strong><p>${d}</p></div>`).join('')}</div><a class="btn" href="#network-map">${icon('network')}View network diagram</a></section></div>`}
function loginPage(){return `<main class="login" id="main" tabindex="-1"><div class="login-intro"><a href="#dashboard" class="brand"><span class="brand-mark">${icon('shield')}</span><div><strong>sentinel.</strong><small>SECURITY OPERATIONS</small></div></a><h1>Every signal.<br>A clearer picture.</h1><p>A focused workspace for network monitoring,<br>threat investigation, and security intelligence.</p><div class="login-visual"><div class="inner">${icon('shield')}</div></div><p style="font-size:11px">Web Technologies · NIDS frontend prototype</p></div><section class="panel"><div class="eyebrow">Demo access</div><h2>Welcome to your SOC</h2><p style="font-size:12px">Choose a role to explore the interface.</p><form id="login-form">${field('Demo identity',select('identity',['Alex Morgan · Admin','Jamie Chen · Analyst'],state.role==='Admin'?'Alex Morgan · Admin':'Jamie Chen · Analyst'))}<div class="notice">No password required. This screen simulates role selection and does not authenticate users.</div><button class="btn primary" type="submit">Enter demo workspace ${icon('arrow')}</button></form><p class="help" style="margin-top:25px">Admin: edit sample users, policies, and settings.<br>Analyst: explore monitoring, investigations, and reports.</p><a class="link-btn" href="#dashboard">← Back to overview</a></section></main>`}
function readOnly(){return pageHead(SOC.routes.find(x=>x[0]===route)[1],'This demo screen is available to the Admin role.')+`<section class="panel empty">${icon('lock')}<h2 style="margin-top:15px">Administrator workspace</h2><p>Your current demo role is Analyst. Switch to Admin to explore this configuration screen.</p><a class="btn primary" href="#login">Switch demo role</a><p class="help">This is a presentation-only role guard, not a security boundary.</p></section>`}
const pages={dashboard,alerts:alertsPage,'threat-details':detailPage,'network-map':networkPage,'system-health':healthPage,users:usersPage,'network-settings':()=>settingsPage('network-settings'),'ai-settings':()=>settingsPage('ai-settings'),'ip-manager':ipPage,reports:reportsPage,'log-archive':archivePage,'traffic-history':trafficPage,'attack-types':attackPage,'threat-intelligence':intelPage,'alert-settings':()=>settingsPage('alert-settings'),'activity-logs':activityPage,help:helpPage};
function render(){const [r,id]=location.hash.slice(1).split('/');route=r||'dashboard';if(route==='threat-details'&&state.alerts.some(a=>a.id===id))state.selected=id;if(!pages[route]&&route!=='login'){route='dashboard';history.replaceState(null,'','#dashboard')}$('#app').innerHTML=route==='login'?loginPage():shell(state.role!=='Admin'&&adminRoutes.includes(route)?readOnly():pages[route]());document.title=`${SOC.routes.find(x=>x[0]===route)?.[1]||'Dashboard'} | Sentinel SOC`;}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function log(action,category='Configuration'){state.activities.unshift({time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),actor:state.role==='Admin'?'Alex Morgan':'Jamie Chen',action,category})}
function openModal(title,body){$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}`;$('#modal').showModal()}
function userModal(id){const u=state.users.find(u=>u.id===id)||{name:'',email:'',role:'Analyst',status:'Active'};openModal(id?'Edit demo user':'Add demo user',`<form id="user-form" data-id="${id||''}">${field('Full name',`<input name="name" required maxlength="70" value="${esc(u.name)}">`)}${field('Email',`<input type="email" name="email" required value="${esc(u.email)}">`)}<div class="form-grid">${field('Role',select('role',['Admin','Analyst'],u.role))}${field('Status',select('status',['Active','Inactive'],u.status))}</div><button class="btn primary" type="submit">Save demo user</button></form>`)}
function ipModal(){openModal('Add IP policy',`<form id="ip-form">${field('IPv4 address','<input name="ip" required placeholder="203.0.113.24">')}${field('Policy',select('policy',['Blocked','Allowed'],'Blocked'))}${field('Reason','<input name="reason" required maxlength="120" placeholder="Reason for this sample policy">')}<p class="help">No firewall changes will occur.</p><button class="btn primary" type="submit">Add demo policy</button></form>`)}
function confirmDelete(kind,id){let record=state[kind].find(x=>x.id===id);openModal('Remove sample record?',`<p class="help">Remove ${esc(record.name||record.ip)} from this session? Reloading restores the original fixtures.</p><div class="actions">${btn('Cancel','close-modal')}<button class="btn danger" data-confirm-delete="${kind}:${id}">Remove record</button></div>`)}
function validIP(ip){return /^(\d{1,3}\.){3}\d{1,3}$/.test(ip)&&ip.split('.').every(v=>+v<=255&&String(+v)===v)}
/* Quote all CSV cells, neutralize spreadsheet formulas, revoke temporary URLs. */
function downloadCSV(name,rows){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});let link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),500);toast('Sample CSV downloaded');}
const alertCSV=rows=>[['ID','Date','Time','Source IP','Destination IP','Attack','Severity','Confidence (%)','Status'],...rows.map(a=>[a.id,a.date,a.time,a.source,a.destination,a.type,a.severity,a.confidence,a.status])];
function searchModal(){openModal('Find a screen',`<label class="field">Search the 18 interfaces<input id="route-search" placeholder="Try reports or network…" autofocus></label><div class="search-results" id="route-results">${routeResults('')}</div>`)}
function routeResults(q){return SOC.routes.filter(r=>r[1].toLowerCase().includes(q.toLowerCase())).map(r=>`<a href="#${r[0]}" data-close-on-nav>${icon(r[2])}${r[1]}<span class="muted" style="margin-left:auto;font-size:10px">Module ${r[4]}</span></a>`).join('')||'<p class="empty">No screens found.</p>'}
const actions={menu:()=>{let open=$('.sidebar').classList.toggle('open');$('[data-action="menu"]').setAttribute('aria-expanded',open)},theme:()=>document.body.classList.toggle('dark'),search:searchModal,'close-modal':()=>$('#modal').close(), 'add-user':()=>userModal(), 'add-ip':ipModal,'reset-alerts':()=>{state.filter={q:'',severity:'All',type:'All',status:'All'};render()},'export-alerts':()=>downloadCSV('sentinel-alerts-sample.csv',alertCSV(filteredAlerts())),'export-report':()=>downloadCSV('sentinel-report-sample.csv',alertCSV(reportRows())),'export-archive':()=>downloadCSV('sentinel-archive-sample.csv',alertCSV(state.alerts.filter(a=>[a.id,a.source,a.type,a.date].join(' ').toLowerCase().includes(state.archiveQ.toLowerCase())))),'export-activity':()=>downloadCSV('sentinel-activity-sample.csv',[['Time','Actor','Activity','Category'],...activityRows().map(a=>[a.time,a.actor,a.action,a.category])]),print:()=>window.print(),'export-types':()=>downloadCSV('sentinel-attack-distribution-sample.csv',[['Category','Sample count','Percentage'],...SOC.attackMix.map(x=>[x[0],x[1],x[1]])]),'export-traffic':()=>{let d=SOC.traffic[state.period];downloadCSV('sentinel-traffic-'+state.period+'-sample.csv',[['Period','Interval index','Normal packets (thousands)','Malicious packets (thousands)'],...d.normal.map((x,i)=>[state.period,i+1,x,d.malicious[i]])])},'refresh-health':()=>toast('Sample status refreshed. No live service is connected.'),'reset-settings':()=>{delete state.settings[route];render();toast('Default demo settings restored')},'preview-notification':()=>openModal('Notification preview',`<div class="notice"><b>Sentinel · Critical sample alert</b><br>DDoS pattern detected from 203.0.113.24.<br>ALT-2048 · 99.2% illustrative confidence</div><p class="help">Preview only. No notification was sent.</p>`),summary:()=>{let a=state.alerts.find(a=>a.id===state.selected);openModal(a.id+' · Quick summary',`<p>${badge(a.severity)} ${badge(a.status)}</p><p class="help">${esc(a.reason)}</p><dl class="detail-list"><div><dt>Source → Target</dt><dd>${a.source} → ${a.destination}</dd></div><div><dt>Sample confidence</dt><dd>${a.confidence}%</dd></div></dl>`)},investigate:()=>setAlertStatus('Investigating'),'close-alert':()=>setAlertStatus('Closed'),'block-threat':()=>{if(state.role!=='Admin')return;let a=state.alerts.find(x=>x.id===state.selected),existing=state.ips.find(x=>x.ip===a.source);if(existing)existing.policy='Blocked';else state.ips.push({id:Date.now(),ip:a.source,policy:'Blocked',reason:a.type+' investigation',added:'22 Oct 2026'});log('Blocked sample IP '+a.source);toast('Sample IP policy updated. No network traffic is blocked.')}};
function setAlertStatus(status){let a=state.alerts.find(x=>x.id===state.selected);a.status=status;log(`${status==='Closed'?'Closed':'Investigating'} alert ${a.id}`,'Investigation');render();toast('Sample alert status updated')}
document.addEventListener('click',e=>{const target=e.target.closest('button,a');if(!target)return;if(target.dataset.action&&actions[target.dataset.action])actions[target.dataset.action]();if(target.dataset.period){state.period=target.dataset.period;render()}if(target.hasAttribute('data-close-on-nav'))$('#modal').close();if(target.dataset.editUser)userModal(+target.dataset.editUser);if(target.dataset.deleteUser)confirmDelete('users',+target.dataset.deleteUser);if(target.dataset.deleteIp)confirmDelete('ips',+target.dataset.deleteIp);if(target.dataset.confirmDelete){let [kind,id]=target.dataset.confirmDelete.split(':');state[kind]=state[kind].filter(x=>x.id!==+id);log('Removed sample '+(kind==='users'?'user':'IP policy'));$('#modal').close();render();toast('Sample record removed')}if(target.dataset.toggleIp){let x=state.ips.find(x=>x.id===+target.dataset.toggleIp);x.policy=x.policy==='Blocked'?'Allowed':'Blocked';log('Updated sample IP policy '+x.ip);render();toast('Sample policy updated')}if(target.closest('.sidebar')&&target.tagName==='A')$('.sidebar')?.classList.remove('open')});
document.addEventListener('input',e=>{let t=e.target;if(t.id==='route-search')$('#route-results').innerHTML=routeResults(t.value);if(t.name==='threshold')$('#threshold-value').textContent=t.value+'%';if(t.id==='alert-q'){state.filter.q=t.value;$('#alert-results').innerHTML=alertTable(filteredAlerts())+`<div class="table-foot">${filteredAlerts().length} matching alerts · Sample dataset</div>`}if(t.id==='archive-q'){state.archiveQ=t.value;$('#archive-results').innerHTML=archiveTable(state.alerts.filter(a=>[a.id,a.source,a.type,a.date].join(' ').toLowerCase().includes(t.value.toLowerCase())))}if(t.id==='activity-q'){state.activityQ=t.value;$('#activity-results').innerHTML=activityTable()}});
document.addEventListener('change',e=>{let t=e.target;if(['alert-severity','alert-type','alert-status'].includes(t.id)){state.filter[t.id.replace('alert-','')]=t.value;render()}if(t.id.startsWith('report-')){let k=t.id.replace('report-',''),next={...state.report,[k]:t.value};if(!next.from||!next.to||next.from>next.to){toast('Choose a valid range: From must be on or before To.');t.value=state.report[k];return}state.report=next;render()}});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));if(f.id==='login-form'){state.role=d.identity.includes('Admin')?'Admin':'Analyst';log('Entered '+state.role+' demo','Session');location.hash='dashboard';toast(state.role+' demo opened')}if(f.id==='user-form'){d.name=d.name.trim();d.email=d.email.trim();if(!d.name)return toast('Enter a name.');let id=+f.dataset.id;if(state.users.some(u=>u.email.toLowerCase()===d.email.toLowerCase()&&u.id!==id))return toast('A demo user already has this email.');if(id)Object.assign(state.users.find(u=>u.id===id),d);else state.users.push({id:Date.now(),...d});log((id?'Edited':'Added')+' demo user '+d.name);$('#modal').close();render();toast('Demo user saved')}if(f.id==='ip-form'){d.ip=d.ip.trim();d.reason=d.reason.trim();if(!validIP(d.ip))return toast('Enter a valid IPv4 address, such as 203.0.113.24.');if(!d.reason)return toast('Enter a reason.');if(state.ips.some(x=>x.ip===d.ip))return toast('This IP already has a policy.');state.ips.push({id:Date.now(),...d,added:'22 Oct 2026'});log('Added sample IP policy '+d.ip);$('#modal').close();render();toast('Sample policy added')}if(f.id==='settings-form'){if(f.dataset.kind==='network-settings'){let [ip,prefix]=d.subnet.split('/');if(!validIP(d.address)||!validIP(ip)||!/^\d{1,2}$/.test(prefix||'')||+prefix>32)return toast('Enter a valid IPv4 sensor address and CIDR subnet.')}f.querySelectorAll('input[type=checkbox]').forEach(x=>d[x.name]=x.checked);state.settings[f.dataset.kind]={...d,saved:true};log('Saved demo '+f.dataset.kind);toast('Settings saved for this session only')}if(f.id==='lookup-form'){let ip=d.ip.trim();if(!validIP(ip))return toast('Enter a valid IPv4 address.');state.lookup=ip;render()}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();searchModal()}if(e.key==='Escape')$('.sidebar')?.classList.remove('open')});
window.addEventListener('hashchange',()=>{$('#modal').close();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});
render();
